import React, { useState } from 'react';
import AccountSettings from './ProductsPageAccountSettings';
import SecurityCard from './SecurityCard';
import ProfileCard from './ProfileCard';
import NotificationSettings from './NotificationSettings';
import DisplaySettings from './DisplaySettings';
import PrivacySettings from './PrivacySettings';
import { 
  Settings, Shield, Bell, Palette, 
  Lock, User, Globe, Database
} from 'lucide-react';

const SettingsPage = () => {
  const [activeTab, setActiveTab] = useState('general');

  const tabs = [
    { id: 'general', label: 'Général', icon: <Settings className="h-5 w-5" /> },
    { id: 'account', label: 'Compte', icon: <User className="h-5 w-5" /> },
    { id: 'security', label: 'Sécurité', icon: <Shield className="h-5 w-5" /> },
    { id: 'notifications', label: 'Notifications', icon: <Bell className="h-5 w-5" /> },
    { id: 'display', label: 'Affichage', icon: <Palette className="h-5 w-5" /> },
    { id: 'privacy', label: 'Confidentialité', icon: <Lock className="h-5 w-5" /> }
  ];

  return (
    <>
      {/* Header */}
      <div className="mb-8">
        <div className="flex items-start justify-between mb-6">
          <div>
            <h1 className="text-2xl md:text-3xl font-bold text-neutral-900 dark:text-white bg-gradient-to-r from-primary-600 to-secondary-600 bg-clip-text text-transparent">
              Paramètres
            </h1>
            <p className="text-sm md:text-base text-neutral-600 dark:text-neutral-400 mt-1">
              Personnalisez votre expérience et gérez vos préférences
            </p>
          </div>
          <div className="flex items-center space-x-2">
            <span className="px-3 py-1 text-xs font-medium bg-primary-100 dark:bg-primary-900/30 text-primary-700 dark:text-primary-300 rounded-full">
              Admin
            </span>
          </div>
        </div>

        {/* Navigation tabs */}
        <div className="flex flex-wrap gap-2 p-1 bg-white dark:bg-neutral-800 rounded-2xl border border-neutral-200 dark:border-neutral-700 max-w-full overflow-x-auto">
          {tabs.map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`flex items-center space-x-2 px-5 py-3 rounded-xl text-sm font-medium transition-all duration-300 whitespace-nowrap ${
                activeTab === tab.id
                  ? 'bg-gradient-to-r from-primary-500 to-secondary-500 text-white shadow-lg'
                  : 'text-neutral-600 dark:text-neutral-400 hover:bg-neutral-100 dark:hover:bg-neutral-700'
              }`}
            >
              {tab.icon}
              <span>{tab.label}</span>
            </button>
          ))}
        </div>
      </div>

      {/* Content based on active tab */}
      <div className="transition-all duration-500 ease-out">
        {activeTab === 'general' && (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-2 space-y-6">
              <AccountSettings />
              <NotificationSettings />
            </div>
            <div className="space-y-6">
              <ProfileCard />
              <SecurityCard />
            </div>
          </div>
        )}

        {activeTab === 'account' && (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-2 space-y-6">
              <AccountSettings />
            </div>
            <div className="space-y-6">
              <ProfileCard />
              <SecurityCard />
            </div>
          </div>
        )}

        {activeTab === 'security' && (
          <div className="space-y-6">
            <SecurityCard expanded={true} />
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
              <div className="bg-gradient-to-br from-white to-white/80 dark:from-neutral-900 dark:to-neutral-900/80 backdrop-blur-xl rounded-3xl shadow-xl border border-white/40 dark:border-neutral-800/60 p-6">
                <h3 className="text-lg font-bold text-neutral-900 dark:text-white mb-6 flex items-center">
                  <Lock className="h-5 w-5 mr-2 text-primary-500" />
                  Sessions actives
                </h3>
                <div className="space-y-4">
                  <SessionItem device="MacBook Pro" location="Paris, FR" current={true} />
                  <SessionItem device="iPhone 15" location="Lyon, FR" current={false} />
                  <SessionItem device="Windows PC" location="Marseille, FR" current={false} />
                </div>
              </div>
              <div className="bg-gradient-to-br from-white to-white/80 dark:from-neutral-900 dark:to-neutral-900/80 backdrop-blur-xl rounded-3xl shadow-xl border border-white/40 dark:border-neutral-800/60 p-6">
                <h3 className="text-lg font-bold text-neutral-900 dark:text-white mb-6 flex items-center">
                  <Shield className="h-5 w-5 mr-2 text-primary-500" />
                  Historique de sécurité
                </h3>
                <div className="space-y-3">
                  <SecurityLog action="Connexion réussie" device="MacBook Pro" time="Aujourd'hui, 10:30" />
                  <SecurityLog action="Mot de passe changé" device="iPhone" time="Hier, 15:45" />
                  <SecurityLog action="2FA activé" device="Web" time="2 jours" />
                </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'notifications' && (
          <div className="space-y-6">
            <NotificationSettings expanded={true} />
          </div>
        )}

        {activeTab === 'display' && (
          <DisplaySettings />
        )}

        {activeTab === 'privacy' && (
          <PrivacySettings />
        )}
      </div>

      {/* Save changes bar */}
      <div className="fixed bottom-6 right-6 left-6 lg:left-auto lg:w-96 animate-fadeInUp">
        <div className="bg-gradient-to-br from-white to-white/80 dark:from-neutral-900 dark:to-neutral-900/80 backdrop-blur-xl rounded-2xl shadow-2xl border border-white/40 dark:border-neutral-800/60 p-4 flex items-center justify-between">
          <div>
            <p className="font-medium text-neutral-900 dark:text-white">Modifications non sauvegardées</p>
            <p className="text-sm text-neutral-600 dark:text-neutral-400">Cliquez pour enregistrer vos changements</p>
          </div>
          <div className="flex items-center space-x-3">
            <button className="px-4 py-2 rounded-xl border border-neutral-300 dark:border-neutral-700 text-neutral-700 dark:text-neutral-300 hover:bg-neutral-100 dark:hover:bg-neutral-800 transition-colors">
              Annuler
            </button>
            <button className="px-4 py-2 rounded-xl bg-gradient-to-r from-primary-500 to-secondary-500 text-white hover:shadow-lg hover:shadow-primary-500/25 transition-all duration-300">
              Sauvegarder
            </button>
          </div>
        </div>
      </div>
    </>
  );
};

